// Turns the query results into three Discord embeds plus a plain-text copy for the TL;DR.
const queries = $('Queries').all();
const results = {};
$('Thanos').all().forEach((item, i) => {
  const key = queries[i].json.key;
  results[key] = item.json.status === 'success' ? item.json.data.result : null;
});

const HOUR = 3600;
const DAY = 86400;
const GiB = 1024 ** 3;

const val = (r) => Number(r.value[1]);
const one = (key) => (results[key]?.length ? val(results[key][0]) : null);
const age = (s) => (s >= 2 * DAY ? `${(s / DAY).toFixed(1)}d` : `${Math.round(s / HOUR)}h`);
const gib = (b) => `${(b / GiB).toFixed(1)} GiB`;
const mbps = (b) => `${Math.round(b / 1e6)} Mbps`;
const delta = (now, prev, fmt) => {
  if (now == null) return 'no data';
  if (prev == null || prev === 0) return fmt(now);
  const pct = ((now - prev) / prev) * 100;
  const sign = pct >= 0 ? '+' : '';
  return `${fmt(now)} (${sign}${pct.toFixed(1)}% vs last week)`;
};
const failed = Object.keys(results).filter((k) => results[k] === null);

// Health: exceptions only, one green line per check otherwise.
const health = [];

const firing = results.firing ?? [];
if (firing.length) {
  const names = [...new Set(firing.map((r) => `${r.metric.alertname} (${r.metric.severity})`))];
  health.push(`🔴 Firing now: ${names.join(', ')}`);
} else {
  health.push('✅ No alerts firing');
}

const volsyncBad = [...(results.volsync_oos ?? []), ...(results.volsync_stale ?? [])]
  .map((r) => `${r.metric.obj_namespace}/${r.metric.obj_name}`);
if (volsyncBad.length) {
  health.push(`🔴 VolSync not syncing: ${[...new Set(volsyncBad)].join(', ')}`);
} else {
  health.push(`✅ VolSync: ${one('volsync_total') ?? '?'} sources synced in the last 26h`);
}

const staleList = (key, limit, label) => {
  const rows = results[key] ?? [];
  const stale = rows.filter((r) => val(r) > limit).map((r) => `${label(r.metric)} (${age(val(r))})`);
  const oldest = rows.length ? Math.max(...rows.map(val)) : null;
  return { rows, stale, oldest };
};

const cnpg = staleList('cnpg_age', 26 * HOUR, (m) => m.cnpg_cluster);
health.push(cnpg.stale.length
  ? `🔴 CNPG backups stale: ${cnpg.stale.join(', ')}`
  : `✅ CNPG: ${cnpg.rows.length} clusters backed up (oldest ${age(cnpg.oldest ?? 0)})`);

const lh = staleList('longhorn_backup_age', 36 * HOUR, (m) => `${m.pvc_namespace}/${m.pvc}`);
health.push(lh.stale.length
  ? `🔴 Longhorn backups stale: ${lh.stale.slice(0, 10).join(', ')}${lh.stale.length > 10 ? ` +${lh.stale.length - 10} more` : ''}`
  : `✅ Longhorn: ${lh.rows.length} volumes backed up (oldest ${age(lh.oldest ?? 0)})`);

const etcd = one('etcd_s3_age');
health.push(etcd == null || etcd > 26 * HOUR
  ? `🔴 etcd S3 snapshot: ${etcd == null ? 'no data' : `last one ${age(etcd)} ago`}`
  : `✅ etcd S3 snapshot ${age(etcd)} ago`);

const cron = (results.cronjob_age ?? []).filter((r) => {
  const limit = r.metric.namespace === 'backup-verify' ? 8 * DAY : 26 * HOUR;
  return val(r) > limit;
});
health.push(cron.length
  ? `🔴 CronJobs overdue: ${cron.map((r) => `${r.metric.namespace}/${r.metric.cronjob} (${age(val(r))})`).join(', ')}`
  : `✅ Backup CronJobs (MariaDB, Longhorn, Technitium, restore-verify) succeeded on schedule`);

const loki = $('Loki restore-verify').first().json;
const verify = {};
for (const r of loki?.data?.result ?? []) {
  const tier = r.metric.tier ?? '?';
  verify[tier] ??= { ok: 0, fail: 0 };
  verify[tier][r.metric.status === 'ok' ? 'ok' : 'fail'] += Number(r.value[1]);
}
const tiers = Object.entries(verify);
if (loki?.status !== 'success') {
  health.push('⚠️ Restore-verify: Loki query failed');
} else if (!tiers.length) {
  health.push('🔴 Restore-verify: no RESULT lines in the last 7d');
} else {
  const anyFail = tiers.some(([, v]) => v.fail > 0);
  health.push(`${anyFail ? '🔴' : '✅'} Restore-verify: ${tiers.map(([t, v]) => `${t} ${v.ok}/${v.ok + v.fail} ok`).join(', ')}`);
}

const halted = one('thanos_halted');
const lokiCompact = one('loki_compact_age');
if (halted === 1 || lokiCompact == null || lokiCompact > 6 * HOUR) {
  const bad = [];
  if (halted === 1) bad.push('Thanos compactor HALTED');
  if (lokiCompact == null || lokiCompact > 6 * HOUR) bad.push(`Loki compactor last ran ${lokiCompact == null ? '?' : age(lokiCompact)} ago`);
  health.push(`🔴 ${bad.join('; ')}`);
} else {
  health.push('✅ Thanos and Loki compactors running');
}

// Action items.
const actions = [];

const openPrs = $('GitHub open PRs').first().json.items;
if (!openPrs) {
  actions.push('⚠️ GitHub open-PR query failed');
} else if (openPrs.length) {
  actions.push(`**${openPrs.length} open PR${openPrs.length === 1 ? '' : 's'}:**`);
  for (const pr of openPrs.slice(0, 10)) {
    const days = Math.floor((Date.now() - Date.parse(pr.created_at)) / 86400000);
    actions.push(`• [#${pr.number}](${pr.html_url}) ${pr.title} — ${days}d${pr.draft ? ' (draft)' : ''}`);
  }
  if (openPrs.length > 10) actions.push(`• …and ${openPrs.length - 10} more`);
} else {
  actions.push('✅ No open PRs');
}

const alloc = results.longhorn_alloc ?? [];
if (alloc.length) {
  const low = alloc.some((r) => val(r) < 20 * GiB);
  actions.push(`${low ? '⚠️' : '💾'} Longhorn allocatable (lowest): ${alloc.map((r) => `${r.metric.node.replace('k3s-', '')} ${gib(val(r))}`).join(', ')}`);
}

const full = results.pvc_full ?? [];
actions.push(full.length
  ? `⚠️ PVCs over 80%: ${full.map((r) => `${r.metric.namespace}/${r.metric.persistentvolumeclaim} ${Math.round(val(r) * 100)}%`).join(', ')}`
  : '✅ No Longhorn PVC over 80%');

const certs = results.cert_expiry ?? [];
const expiring = certs.filter((r) => val(r) < 30 * DAY);
const soonest = certs.length ? Math.min(...certs.map(val)) : null;
actions.push(expiring.length
  ? `⚠️ Certs expiring within 30d: ${expiring.map((r) => `${r.metric.name} (${age(val(r))})`).join(', ')}`
  : `✅ Certs: soonest expiry in ${soonest == null ? '?' : age(soonest)}`);

const restarts = results.restarts ?? [];
actions.push(restarts.length
  ? `⚠️ Restarted >3× this week: ${restarts.map((r) => `${r.metric.namespace}/${r.metric.pod} ${r.metric.container} (${Math.round(val(r))})`).join(', ')}`
  : '✅ No container restarted more than 3× this week');

if (failed.length) actions.push(`⚠️ Queries that failed: ${failed.join(', ')}`);

// Trends.
const trends = [];
trends.push(`🌐 Download (median): ${delta(one('speed_down'), one('speed_down_prev'), mbps)}`);
trends.push(`🌐 Upload (median): ${delta(one('speed_up'), one('speed_up_prev'), mbps)}`);
trends.push(`🌐 Ping (median): ${delta(one('speed_ping'), one('speed_ping_prev'), (v) => `${v.toFixed(1)} ms`)}`);
trends.push(`💾 Longhorn used: ${delta(one('longhorn_used'), one('longhorn_used_prev'), gib)}`);

const decPrev = Object.fromEntries((results.crowdsec_decisions_prev ?? []).map((r) => [r.metric.origin, val(r)]));
for (const r of results.crowdsec_decisions ?? []) {
  trends.push(`🛡️ CrowdSec ${r.metric.origin} bans: ${delta(val(r), decPrev[r.metric.origin], (v) => Math.round(v).toLocaleString('en-US'))}`);
}
trends.push(`🛡️ AppSec blocks this week: ${Math.round(one('crowdsec_blocks') ?? 0)}`);

// Merged this week: hand-written PRs listed, Renovate rolled up.
const merged = $('GitHub merged PRs').first().json.items;
const mergedLines = [];
if (!merged) {
  mergedLines.push('⚠️ GitHub merged-PR query failed');
} else if (!merged.length) {
  mergedLines.push('Nothing merged this week');
} else {
  const isBot = (pr) => pr.user?.login === 'renovate[bot]';
  const byMerge = (a, b) => Date.parse(b.pull_request?.merged_at) - Date.parse(a.pull_request?.merged_at);
  const mine = merged.filter((pr) => !isBot(pr)).sort(byMerge);
  const deps = merged.filter(isBot);
  for (const pr of mine.slice(0, 15)) {
    const title = pr.title.length > 80 ? `${pr.title.slice(0, 77)}…` : pr.title;
    mergedLines.push(`• [#${pr.number}](${pr.html_url}) ${title}`);
  }
  if (mine.length > 15) mergedLines.push(`• …and ${mine.length - 15} more`);
  if (deps.length) mergedLines.push(`• ${deps.length} Renovate dependency update${deps.length === 1 ? '' : 's'}`);
}

const now = new Date().toISOString();
const anyRed = health.some((l) => l.startsWith('🔴'));
const embeds = [
  { title: 'Health', description: health.join('\n'), color: anyRed ? 0xe74c3c : 0x2ecc71, timestamp: now },
  { title: 'Action items', description: actions.join('\n').slice(0, 4000), color: 0xf1c40f },
  { title: 'Trends', description: trends.join('\n'), color: 0x3498db },
  { title: `Merged this week (${merged?.length ?? '?'})`, description: mergedLines.join('\n').slice(0, 2000), color: 0x9b59b6 },
];

const tldrInput = embeds.map((e) => `## ${e.title}\n${e.description}`).join('\n\n');

return [{ json: { embeds, tldrInput } }];
